#!/bin/sh
# Runs once on an empty PostgreSQL data volume.
#
# Local development keeps the default PostgreSQL rules because the database is
# only reachable on the private Docker network. Cloud deployment sets
# MESH_REQUIRE_DB_TLS=true so every TCP connection must use TLS.
#
# Existing volumes do not re-run this script. For an existing cloud volume,
# apply the same pg_hba.conf manually and reload PostgreSQL.

set -eu

if [ "${MESH_REQUIRE_DB_TLS:-false}" = "true" ]; then
  cat > "$PGDATA/pg_hba.conf" <<'EOF'
# Generated by db/init/02-require-tls.sh.
# Local socket access is trusted inside the container; every TCP connection
# must use TLS and SCRAM-SHA-256 authentication.
local   all             all                                     trust
hostssl all             all             0.0.0.0/0               scram-sha-256
hostssl all             all             ::/0                    scram-sha-256
EOF
  echo "pg_hba.conf updated: TLS is required for all TCP connections."
else
  echo "pg_hba.conf unchanged: MESH_REQUIRE_DB_TLS is not true."
fi
